function taskEditIcon(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M10 4H5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h13a2 2 0 0 0 2-2v-6M14 5l5 5M10 16l-1 4 4-1L22 10a2 2 0 0 0 0-3l-2-2a2 2 0 0 0-3 0z"/></svg>';}
