      app.innerHTML='<div class="heading"><div><h1>Purchase Order</h1><span class="muted">外部供应商采购单 · 只登记关联，不开正式单据</span></div></div><section class="panel"><table class="directory"><thead><tr><th>P.O. Number</th><th>Tasks / 产品任务</th><th>Supplier CTN</th><th>Supplier</th><th></th></tr></thead><tbody>'+[...groups.values()].map(rows=>`<tr><td><b>${esc(rows[0].po)}</b></td><td>${rows.length}</td><td>${rows.every(row=>Number.isSafeInteger(row.procurement?.totalCtn))?rows.reduce((n,row)=>n+row.procurement.totalCtn,0):'—'}</td><td>${esc(supplierName(rows[0].supplierId))}</td><td>${button('Details ↗',`data-po-view="${esc(rows[0].id)}"`)}</td></tr>`).join('')+'</tbody></table></section>';
