    if(control.id==='saveSupplierPlan'){const row=data.tasks.find(row=>row.id===dialogContext.taskId),totalCtn=Number(document.querySelector('#planTotal').value),reason=document.querySelector('#planReason').value.trim(),extraKind=document.querySelector('#planExtraKind').value,confirmExtra=document.querySelector('#planConfirmExtra').checked,supplierConfirmed=row.po?document.querySelector('#planSupplierConfirmed').checked:false;if(row.procurement?.revision&&totalCtn===row.procurement.totalCtn){document.querySelector('#dialogError').textContent='供货数量没有变化，无需保存。';return;}if(!Number.isSafeInteger(totalCtn)||totalCtn<row.ord||totalCtn>9999||!reason){document.querySelector('#dialogError').textContent='请填写供货总箱数（不少于客户数量）和数量变动原因。';return;}if(totalCtn>row.ord&&(!confirmExtra||!['FREE_GOODS','PAID_EXTRA'].includes(extraKind))){document.querySelector('#dialogError').textContent='请确认多余数量，并选择赠品或额外采购。';return;}if(row.po&&!supplierConfirmed){document.querySelector('#dialogError').textContent='请先与供应商确认本次 P.O. 的供货数量，再勾选确认。';return;}return mutate('PURCHASE_SAVE_REQUEST',{operation:'PLAN',input:{taskId:row.id,version:row.editVersion,planRevision:row.procurement?.revision||'',totalCtn,reason,extraKind,confirmExtra,supplierConfirmed}});}
