    if(control.id==='addCustomer'){document.querySelector('#dialogContent').innerHTML='<h2>Add Customer</h2><p>客户身份与注册资料由 Sales Room 管理。</p><p><a class="btn primary" href="https://fmcg999.wixstudio.com/fmcgmalaysia/sales-room" target="_blank" rel="noopener">Open Sales Room</a></p><footer>'+button('Close','id="closeModal"')+'</footer>';modal.showModal();return;}
    if(control.dataset.stage!==undefined){const stage=Number(control.dataset.stage);if(highlightTimer)clearTimeout(highlightTimer);for(const el of document.querySelectorAll('tr[data-id]')){const row=data.tasks.find(row=>row.id===el.dataset.id);el.classList.toggle('highlight',row&&stageIndex(row)>=0&&stageIndex(row)<=stage);}highlightTimer=setTimeout(()=>{for(const el of document.querySelectorAll('tr[data-id]'))el.classList.remove('highlight');highlightTimer=null;},3000);return;}
    if(control.id==='riskFilter'){const rows=roomRows().filter(row=>row.risk);return formDialog('RISK / 高风险交易',rows.length+' rows',rows.length?'<table class="rowlist"><thead><tr><th>Row</th><th>DESCRIPTION</th><th>GP</th><th>RISK</th></tr></thead><tbody>'+rows.map(row=>'<tr><td>'+String(roomRows().indexOf(row)+1).padStart(3,'0')+'</td><td><b>'+esc(row.name)+'</b><small>'+esc(row.barcode)+'</small></td><td>—</td><td>'+esc(row.riskReason||'Receipt Risk / 来货差异')+'</td></tr>').join('')+'</tbody></table>':'<div class="note">目前没有已知的高风险交易。<br>No known high-risk rows.</div>');}
    if(control.id==='clearSelection'){selected.clear();return render();}
    if(control.dataset.poView){const first=data.tasks.find(row=>row.id===control.dataset.poView);if(!first)return;const rows=data.tasks.filter(row=>row.po===first.po&&row.customerId===first.customerId&&row.supplierId===first.supplierId);return formDialog('P.O. Details / 采购单详情',supplierName(first.supplierId),`<div class="po-items-summary">OUR P.O. NO. <b>${esc(first.po)}</b></div><table class="rowlist po-items"><colgroup><col style="width:24%"><col style="width:58%"><col style="width:18%"></colgroup><thead><tr><th>BARCODE</th><th>ITEM / PACKING</th><th>QTY / CTN</th></tr></thead><tbody>${rows.map(row=>`<tr><td class="po-barcode">${esc(row.barcode)}</td><td><b>${esc(row.name)}</b><small>${esc(row.packing)}</small></td><td class="po-quantity">${qtyDigits(row.procurement?.totalCtn)}</td></tr>`).join('')}</tbody></table>`,'','po');}

